def write_tiny_pipe_delimited_files(target_dir: Path) -> Tuple[Path, Path]:
    """Write synthetic raw pipe-delimited text files mimicking Freddie Mac R47 files."""
    target_dir.mkdir(parents=True, exist_ok=True)
    df_orig, df_perf = generate_tiny_panel_dfs()

    orig_path = target_dir / "sample_orig_2006.txt"
    perf_path = target_dir / "sample_perf_2006.txt"

    # Write without headers, pipe delimited, handling NaN as empty string
    df_orig.to_csv(orig_path, sep="|", header=False, index=False)
    df_perf.to_csv(perf_path, sep="|", header=False, index=False)

    return orig_path, perf_path
